/* Raaf, Parathyroid Disease 2026. Fourteen supplied objectives in order.
 * Labeled guideline completions correct calcium interpretation and complete current treatment decisions.
 */
(function(){
  "use strict";
  function q(prompt,answer,wrong,explanation){return {prompt:prompt,choices:[answer].concat(wrong),correct:0,explanation:explanation};}
  function u(title,html,coverage,test,apply){return {title:title,html:html,coverage:coverage,test:test,apply:apply};}
  function s(id,title,description,units){var r={id:id,title:title,description:description,cards:[],test:[],apply:[]};units.forEach(function(x,i){r.cards.push({title:x.title,html:x.html,coverage:x.coverage});["test","apply"].forEach(function(m){x[m].forEach(function(z){z.card=i;r[m].push(z);});});});return r;}
  function ref(url,label){return '<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+label+'</a>';}
  var phpt=ref('https://jsbmr.umin.jp/guide/pdf/Bilezikian-2022-Evaluation-and-management-of-primar.pdf','Fifth International Workshop: primary hyperparathyroidism');
  var ckd=ref('https://pmc.ncbi.nlm.nih.gov/articles/PMC6340919/','KDIGO CKD-MBD guideline');
  var hcm=ref('https://www.endocrine.org/clinical-practice-guidelines/hypercalcemia','Endocrine Society: hypercalcemia of malignancy');
  var hypo=ref('https://pmc.ncbi.nlm.nih.gov/articles/PMC10118814/','2022 International Task Force: hypoparathyroidism');
  window.PARATHYROID_DISEASE_OBJECTIVES=[
    s('01-calcium-vitamin-d','1. Calcium metabolism and vitamin D production','Objective 1. Slides 3–24.',[
      u('Calcium pools and essential functions','<p><strong>About 99%</strong> of body calcium is stored in the skeleton. The circulating/soft-tissue fraction supports nerve and muscle excitability, intracellular signaling, enzyme activity and clotting.</p><p>About half of serum calcium is <strong>ionized and biologically active</strong>; much of the rest is albumin-bound. Bone serves as both structure and a calcium reservoir.</p>',['calcium99-bone','calcium1-circulating','ionized-active-albumin','calcium-nerve-muscle-signal-clot','bone-reservoir'],[
        q('Which calcium fraction is biologically active?','Ionized calcium',['Albumin-bound calcium only','Calcium stored in bone only','Urinary calcium only'],'Ionized calcium directly affects cell membranes and signaling.'),
        q('Where is most body calcium stored?','The skeleton',['Plasma','The liver','The parathyroid glands'],'Bone contains about 99% and acts as a reservoir.')
      ],[q('A patient has neuromuscular symptoms but a misleading total calcium because albumin is abnormal. Which measurement most directly reflects active calcium?','Ionized calcium',['Bone density','Serum albumin alone','Urine phosphate'],'The ionized fraction drives membrane excitability.')]),
      u('PTH, calcitonin, and osteoclasts','<p>Low ionized calcium stimulates parathyroid <strong>PTH</strong>. PTH raises serum calcium through kidney calcium retention, renal phosphate loss, stimulation of calcitriol production, and increased bone resorption.</p><p>PTH influences osteoclast activity indirectly through osteoblast-lineage signaling. <strong>Calcitonin</strong> from thyroid C cells inhibits osteoclast-mediated resorption, although it has a smaller day-to-day role in adult calcium control.</p>',['low-ca-pth','pth-kidney-bone-vitd','pth-osteoclast-indirect','calcitonin-c-cells','calcitonin-inhibits-osteoclast'],[
        q('What happens to PTH when ionized calcium falls?','PTH secretion increases',['PTH is fully suppressed','Calcitonin becomes the only calcium regulator','Kidney phosphate excretion stops because PTH rises'],'The calcium-sensing receptor detects the fall.'),
        q('What is calcitonin’s main bone action?','Inhibits osteoclast-mediated bone resorption',['Stimulates PTH release','Activates renal 1-alpha-hydroxylase','Increases intestinal phosphate absorption'],'Calcitonin reduces calcium release from bone.')
      ],[q('Serum calcium falls. Which response raises it over both short and longer time frames?','PTH increases renal calcium retention and bone resorption, then increases calcitriol-mediated gut absorption',['Calcitonin increases osteoclast activity','PTH increases renal calcium loss','The liver directly secretes PTH'],'PTH coordinates bone, kidney and intestine through vitamin D.')]),
      u('Vitamin D activation','<p>Skin UV exposure produces vitamin D precursor; food/supplements provide <strong>D2 (ergocalciferol)</strong> or <strong>D3 (cholecalciferol)</strong>.</p><p><strong>Liver:</strong> first hydroxylation makes <strong>25-hydroxyvitamin D [25(OH)D]</strong>, the usual status test. <strong>Kidney:</strong> 1-alpha-hydroxylation makes active <strong>1,25-dihydroxyvitamin D (calcitriol)</strong>, stimulated by PTH.</p>',['vitd-skin-d2-d3','vitd-liver25','vitd-25-status','vitd-kidney125','vitd-pth-activation'],[
        q('Which vitamin D measurement best reflects body stores?','25-hydroxyvitamin D',['1,25-dihydroxyvitamin D in every setting','PTHrP','Urine calcium alone'],'The liver-produced 25(OH)D is the usual status marker.'),
        q('Where is active calcitriol normally produced?','Kidney, by 1-alpha-hydroxylation',['Parathyroid gland','Bone marrow','Thyroid C cells'],'The kidney completes activation after liver hydroxylation.')
      ],[q('A patient with advanced CKD has low calcitriol despite adequate precursor. Which lost step explains this?','Reduced renal 1-alpha-hydroxylation',['Failure of parathyroid glands to produce D3','Failure of osteoclasts to make 25(OH)D','Excess thyroid calcitonin converting calcitriol to PTH'],'Kidney disease disrupts the final activation step.')]),
      u('Active vitamin D links intestine to calcium balance','<p>Calcitriol increases <strong>small-intestinal absorption of calcium and phosphate</strong>. The kidney also controls urinary calcium/phosphate, while bone buffers extracellular calcium.</p><p>Macrophage 1-alpha-hydroxylase in granulomatous disease or lymphoma can produce calcitriol outside normal PTH control, causing hypercalcemia. Excess vitamin D supplementation more often raises 25(OH)D.</p>',['calcitriol-gut-ca-phos','kidney-urine-control','bone-buffer','granuloma-extra-renal125','supplement-toxicity25'],[
        q('What does calcitriol do in the small intestine?','Increases calcium and phosphate absorption',['Blocks all calcium absorption','Causes only renal phosphate loss','Directly secretes calcitonin'],'This is the indirect intestinal arm of PTH action.'),
        q('Why can sarcoidosis cause hypercalcemia?','Unregulated extra-renal calcitriol production increases gut calcium absorption',['It always secretes PTHrP','It destroys albumin only','It prevents all vitamin D activation'],'Granulomatous macrophages can activate vitamin D.')
      ],[q('A patient with sarcoidosis has low PTH and high calcitriol with hypercalcemia. Which mechanism fits?','Extra-renal vitamin D activation driving intestinal calcium absorption',['Primary parathyroid adenoma','Failure to absorb calcium from the gut','Calcitonin excess'],'The hormone pattern points to calcitriol-mediated hypercalcemia.')])
    ]),
    s('02-pth-actions','2. PTH actions and calcium homeostasis','Objective 2. Slides 15–17.',[
      u('Three target effects of PTH','<ol><li><strong>Bone:</strong> increases calcium release through increased resorption.</li><li><strong>Kidney:</strong> increases calcium reabsorption and decreases phosphate reabsorption, causing phosphaturia.</li><li><strong>Vitamin D:</strong> stimulates renal calcitriol production, which increases intestinal calcium/phosphate absorption.</li></ol><p>Net effect: serum calcium rises; serum phosphate often falls when renal function permits.</p>',['pth-bone-release','pth-renal-ca-retain','pth-phosphaturia','pth-calcitriol-gut','pth-net-ca-up-phos-down'],[
        q('What does PTH do to renal calcium and phosphate handling?','Retains calcium and excretes phosphate',['Excretes calcium and retains phosphate','Retains both without exception','Excretes both as its main action'],'This creates the classic high-calcium/low-phosphate pattern in primary disease.'),
        q('How does PTH increase intestinal calcium absorption?','Indirectly by increasing renal calcitriol production',['By entering the gut and transporting calcium itself','By suppressing all vitamin D','Through calcitonin release'],'PTH acts on the kidney; calcitriol acts on the intestine.')
      ],[q('A patient has excess PTH and functioning kidneys. Which lab direction follows the hormone’s net actions?','Calcium rises and phosphate falls',['Calcium falls and phosphate rises','Both always remain normal','Calcium and phosphate both fall solely from intestinal blockade'],'Kidney phosphate wasting distinguishes the usual primary pattern.')]),
      u('Calcium feedback closes the loop','<p>Parathyroid calcium-sensing receptors increase PTH when ionized calcium falls and suppress PTH when calcium rises. Therefore, a “normal” PTH can be <strong>inappropriately high</strong> during hypercalcemia.</p><p>Magnesium is also required for normal PTH secretion/action; severe hypomagnesemia can cause low secretion and resistance.</p>',['casr-feedback','high-ca-suppresses-pth','inappropriate-normal-pth','magnesium-pth'],[
        q('What is an appropriate PTH response to hypercalcemia?','Suppression to a low level',['Elevation above normal','No change regardless of calcium','Conversion into PTHrP'],'If PTH is not suppressed, a PTH-dependent cause is possible.'),
        q('How can severe hypomagnesemia cause hypocalcemia?','It impairs PTH secretion and causes PTH resistance',['It causes autonomous PTH secretion','It directly creates PTHrP','It always raises calcitriol excessively'],'Magnesium correction can be necessary for calcium correction.')
      ],[q('Calcium is repeatedly high and PTH is mid-normal. Why is that result abnormal?','PTH should be suppressed, so a normal value is inappropriate',['PTH must always be high in healthy people','A normal PTH proves malignancy','PTH has no relationship to calcium'],'Interpret PTH relative to the calcium level.')])
    ]),
    s('03-calcium-symptoms','3. Signs and symptoms of low and high calcium','Objective 3. Slides 7–12, 25–33.',[
      u('Confirm whether the calcium is truly abnormal','<p>Total calcium depends on albumin. Repeat an unexpected value with albumin or measure <strong>ionized calcium</strong>, especially when illness, acid-base disturbance, or major albumin abnormality makes correction unreliable.</p><p><strong>Correction:</strong> a common estimate is corrected Ca = measured Ca + 0.8 × (4 − albumin), not the slide’s “Ca + 4 − albumin.” Use lab units/ranges and prefer ionized calcium when accuracy matters.</p>',['total-albumin','repeat-ca-albumin','ionized-preferred-context','corrected-formula08'],[
        q('Why can low albumin make total calcium look low?','Less calcium is protein-bound while ionized calcium may remain normal',['Albumin increases PTHrP','Albumin converts phosphate into calcium','Ionized calcium must always fall equally'],'Total and active calcium can diverge.'),
        q('Which test bypasses albumin correction?','Ionized calcium',['Total protein alone','Alkaline phosphatase','PTHrP'],'Ionized calcium measures the active fraction directly.')
      ],[q('Measured calcium is 7.2 mg/dL and albumin is 2.4 g/dL. Using measured + 0.8 × (4 − albumin), what is the estimate?','8.48 mg/dL',['5.6 mg/dL','9.6 mg/dL','12.0 mg/dL'],'7.2 + 0.8 × 1.6 = 8.48; ionized calcium may still be preferable clinically.')]),
      u('Hypocalcemia makes nerves and muscles more excitable','<p>Early findings: <strong>perioral or distal paresthesias, cramps, carpopedal spasm and tetany</strong>. Chvostek and Trousseau signs support neuromuscular irritability.</p><p>Severe disease can cause <strong>laryngospasm, bronchospasm, seizures and prolonged QT</strong>, with arrhythmia risk.</p>',['hypoca-paresthesia-cramps','hypoca-spasm-tetany','chvostek-trousseau','hypoca-laryngo-seizure','hypoca-long-qt'],[
        q('What is the membrane effect of hypocalcemia?','Lower firing threshold and neuromuscular hyperexcitability',['Higher threshold and reduced excitability','No effect on nerves or muscle','Only increased GI smooth-muscle relaxation'],'Low ionized calcium makes membranes easier to depolarize.'),
        q('Which ECG change is associated with hypocalcemia?','Prolonged QT',['Shortened QT','Fixed ST elevation as the defining sign','No possible cardiac effect'],'Remember low calcium as the longer QT pattern.')
      ],[q('A patient has perioral tingling, carpopedal spasm, and a prolonged QT. Which disorder fits?','Hypocalcemia',['Hypercalcemia','Primary aldosteronism','Pheochromocytoma'],'The symptoms reflect increased neuromuscular excitability.')]),
      u('Hypercalcemia makes nerves and muscles less excitable','<p>Findings include <strong>weakness, hyporeflexia, fatigue</strong>; constipation/ileus, nausea/vomiting; polyuria, volume depletion and AKI; confusion, poor concentration, mood change, stupor or coma.</p><p>Cardiac findings can include <strong>shortened QT</strong>, bradycardia or hypertension. Renal stones and pancreatitis may occur depending on cause/severity.</p>',['hyperca-weak-hyporeflexia','hyperca-gi','hyperca-polyuria-aki','hyperca-neuro','hyperca-short-qt','hyperca-stones-pancreatitis'],[
        q('What is the membrane effect of hypercalcemia?','Raises the depolarization threshold and reduces excitability',['Causes neuromuscular tetany in every case','Lowers the threshold for sodium-channel firing','Has no effect on smooth muscle'],'This explains weakness and slowed GI motility.'),
        q('Which ECG change fits hypercalcemia?','Shortened QT',['Prolonged QT','Complete absence of cardiac effects','Only a widened QRS in every case'],'High calcium is associated with the shorter QT pattern.')
      ],[q('A dehydrated patient has constipation, weakness, confusion, polyuria and a shortened QT. Which electrolyte problem fits?','Hypercalcemia',['Hypocalcemia','Isolated low phosphate','Hypomagnesemia as the only possible cause'],'The multi-system pattern reflects reduced excitability and renal water loss.')]),
      u('Symptoms depend on level, speed, and patient reserve','<p>Symptoms become more likely with a larger abnormality and <strong>rapid change</strong>. Slowly developing disease may remain surprisingly mild at the same number.</p><p>Age, kidney function, volume status and other illnesses alter tolerance. Treat the patient’s symptoms and trajectory, not one universal threshold alone.</p>',['symptoms-severity','symptoms-speed','symptoms-age-comorbidity','symptoms-context-not-number'],[
        q('Why can two patients at the same calcium level feel different?','Rate of change and patient comorbidities modify symptoms',['Calcium symptoms depend only on sex','Albumin makes every patient identical','PTH has no clinical context'],'Acute change is often less tolerated than chronic change.')
      ],[q('One patient reaches calcium 12.3 rapidly and is confused; another has chronic mild symptoms at a similar level. What explains the difference?','Speed of rise and clinical reserve affect presentation',['The same calcium always causes identical symptoms','Only total body calcium stores determine symptoms','The confused patient must have low calcium'],'Urgency depends on symptoms, trajectory and context.')])
    ]),
    s('04-hypocalcemia-treatment','4. Treatment of asymptomatic and symptomatic hypocalcemia','Objective 4. Slides 43–47.',[
      u('Mild or asymptomatic: replace orally and treat the cause','<p>Confirm true hypocalcemia and check <strong>PTH, magnesium, creatinine, phosphate and vitamin D</strong>. Mild stable disease uses dietary calcium and/or oral calcium; add vitamin D or active vitamin D when the cause requires it.</p><p>Calcium carbonate is inexpensive and needs gastric acid/food for best absorption. Calcium citrate is less acid-dependent. Separate calcium from interacting medicines such as thyroid hormone, some antibiotics and oral bisphosphonates.</p>',['hypoca-workup-panel','mild-oral-diet','vitd-cause','carbonate-citrate','calcium-drug-spacing'],[
        q('Which treatment fits stable mild asymptomatic hypocalcemia?','Oral calcium/dietary replacement with cause-specific vitamin D and follow-up',['Automatic central-line calcium chloride','No evaluation of magnesium or kidney function','IV bisphosphonate'],'Stable patients generally receive oral therapy while the cause is corrected.'),
        q('Why might calcium citrate be chosen over carbonate?','It is less dependent on gastric acid for absorption',['It must be given by central line','It causes no drug interactions','It directly replaces PTH'],'Formulation choice can reflect acid suppression or absorption concerns.')
      ],[q('A stable patient with mild hypocalcemia takes levothyroxine. What counseling matters?','Use oral calcium as directed and separate it from levothyroxine',['Take both simultaneously to increase absorption','Use IV calcium indefinitely','Stop evaluating vitamin D and magnesium'],'Calcium can reduce absorption of other medications.')]),
      u('Symptomatic or severe: IV calcium, ECG monitoring, and magnesium','<p>Tetany, seizures, laryngospasm, arrhythmia/QT change or severe acute hypocalcemia needs monitored <strong>IV calcium</strong>. <strong>Calcium gluconate</strong> is commonly used peripherally; calcium chloride provides more elemental calcium but can injure tissue and generally requires central access for emergencies.</p><p>Correct <strong>magnesium deficiency</strong> and the precipitating cause. Transition to oral calcium/vitamin D only after symptoms and calcium stabilize.</p>',['severe-iv-calcium','gluconate-peripheral','chloride-central-emergency','ecg-monitor','correct-magnesium','transition-stable'],[
        q('Which calcium preparation is commonly used IV for symptomatic hypocalcemia?','Calcium gluconate',['Oral calcium carbonate only during a seizure','IV zoledronic acid','Subcutaneous calcitonin'],'Gluconate is commonly used because it is less caustic than chloride.'),
        q('Why must magnesium be checked and corrected?','Severe deficiency impairs PTH secretion/action and can make hypocalcemia refractory',['Magnesium always causes hyperparathyroidism','Magnesium converts calcium into phosphate','It replaces ECG monitoring'],'Calcium may not correct until the PTH pathway can function.')
      ],[q('A patient has seizures, tetany, prolonged QT, low ionized calcium and low magnesium. Which plan fits?','Monitored IV calcium plus magnesium correction and cause treatment',['Oral diet changes alone','An IV bisphosphonate to lower calcium further','Wait for symptoms to resolve without ECG monitoring'],'This is symptomatic severe hypocalcemia requiring urgent replacement.')])
    ]),
    s('05-hypercalcemia-treatment','5. Management of asymptomatic and symptomatic hypercalcemia','Objective 5. Slides 39–40, with current treatment completion.',[
      u('Mild/asymptomatic: hydration and remove aggravators','<p>For stable mild hypercalcemia, encourage appropriate oral hydration and mobility. Review calcium/antacid excess and medicines that can worsen calcium, including <strong>thiazides and lithium</strong>.</p><p>Treat the underlying cause. Avoiding a factor does not replace workup, and hydration must be individualized in heart or kidney disease.</p>',['mild-hyperca-oral-hydration','mobility','avoid-calcium-thiazide-lithium','treat-underlying','fluid-comorbidity'],[
        q('Which initial step fits stable mild asymptomatic hypercalcemia?','Hydrate appropriately and review causes/medications',['Immediate calcium supplementation','Prolonged bed rest','Assume it needs no diagnostic evaluation'],'Mild care still includes cause identification.'),
        q('Which medicines can worsen hypercalcemia?','Thiazides and lithium',['Loop diuretics in every circumstance','Calcium gluconate only','Calcitonin only'],'Medication review is part of management.')
      ],[q('A stable patient has mild hypercalcemia while taking lithium and large calcium-antacid doses. Which first approach fits?','Confirm the disorder, hydrate appropriately, and review contributing exposures',['Add a thiazide','Recommend immobilization','Treat with IV calcium'],'Remove aggravators while completing the cause-specific evaluation.')]),
      u('Severe or symptomatic: isotonic fluid and antiresorptive therapy','<p>Severe symptoms, marked elevation or rapid rise requires urgent monitored care. Restore volume with <strong>isotonic IV fluid</strong>, adjusted for cardiac/renal status.</p><p>Use an <strong>IV bisphosphonate or denosumab</strong> when bone resorption drives the disorder. These take time to work, so the cause and kidney function influence selection.</p>',['severe-hyperca-urgent','iv-isotonic-fluid','fluid-cardiorenal','bisphosphonate-denosumab','cause-kidney-selection'],[
        q('What is the initial volume treatment for severe dehydrating hypercalcemia?','Isotonic IV fluid with close reassessment',['Calcium chloride infusion','Fluid restriction in every patient','A thiazide to retain calcium'],'Volume restoration increases renal calcium clearance.'),
        q('Which therapies provide sustained antiresorptive calcium lowering?','IV bisphosphonate or denosumab',['Oral calcium plus vitamin D','PTH injection','Lithium'],'They suppress calcium release from bone, but onset is not immediate.')
      ],[q('A confused, volume-depleted patient has calcium 15.2 mg/dL. Which initial strategy fits?','Urgent monitored isotonic fluids plus cause-appropriate calcium-lowering therapy',['Outpatient water advice only','Calcium supplementation','Bed rest and thiazide therapy'],'Severe symptomatic hypercalcemia is an emergency.')]),
      u('Rapid adjuncts and cause-specific options','<p><strong>Calcitonin</strong> lowers calcium quickly but loses effect within days, so use it as a short bridge in severe disease. Loop diuretics are not routine calcium therapy; use only for volume overload after rehydration when indicated.</p><p>Glucocorticoids help calcitriol-mediated disease such as lymphoma or granulomatous disease. Dialysis may be needed for life-threatening refractory hypercalcemia when fluids/medicines are unsafe or ineffective.</p>',['calcitonin-fast-bridge','calcitonin-tachyphylaxis','loop-not-routine','glucocorticoid-calcitriol','dialysis-refractory'],[
        q('What is calcitonin’s role in severe hypercalcemia?','Rapid short-term lowering while slower therapy takes effect',['Permanent monotherapy with no loss of effect','A treatment that raises calcium','Replacement of IV fluid in shock'],'Tachyphylaxis limits it to a brief course.'),
        q('When are glucocorticoids useful for hypercalcemia?','Calcitriol-mediated disease such as lymphoma or granulomatous disease',['Every PTH-producing adenoma as definitive therapy','FHH as routine first-line therapy','Severe hypoparathyroidism'],'They reduce abnormal calcitriol production/action in the relevant causes.')
      ],[q('A patient with lymphoma has high calcitriol and severe hypercalcemia. Which cause-specific treatment is useful alongside acute calcium control?','Glucocorticoid therapy',['High-dose vitamin D','Calcium chloride','A thiazide diuretic'],'Calcitriol-driven hypercalcemia responds to glucocorticoid suppression.')])
    ]),
    s('06-hypercalcemia-workup','6. Workup of hypercalcemia','Objective 6. Slides 34–36, completed with urine-calcium differentiation.',[
      u('First confirm the calcium abnormality','<p>Repeat calcium with albumin on another draw or measure ionized calcium. Review symptoms, speed of change, hydration, kidney function, medicines/supplements and prior calcium values.</p><p>Once confirmed, obtain <strong>intact PTH at the same time as calcium</strong>. This first branch separates PTH-dependent from PTH-independent hypercalcemia.</p>',['workup-repeat-corrected-ionized','workup-history-med-kidney','workup-pth-same-draw','workup-pth-branch'],[
        q('What is the key first hormonal test after confirming hypercalcemia?','Intact PTH',['PTHrP before PTH in every patient','ACTH stimulation','TSH receptor antibody'],'PTH establishes the first diagnostic branch.'),
        q('Why repeat calcium with albumin or ionized calcium?','To verify true hypercalcemia rather than protein-related total-calcium distortion',['To diagnose the exact tumor immediately','To calculate PTHrP','To avoid reviewing medications'],'Confirmation precedes etiologic testing.')
      ],[q('A routine panel shows one mildly high total calcium in a dehydrated patient. What comes before labeling a parathyroid disorder?','Repeat/confirm calcium with albumin or ionized calcium and assess context',['Immediate neck surgery','Diagnose malignancy from one value','Start calcium supplementation'],'Verify the abnormality and its active fraction.')]),
      u('PTH high or not suppressed: evaluate PTH-dependent causes','<p>Confirmed high calcium with high or inappropriately normal PTH suggests <strong>primary hyperparathyroidism</strong>, tertiary disease, lithium effect or <strong>familial hypocalciuric hypercalcemia (FHH)</strong>.</p><p>Check creatinine/eGFR, phosphate, 25(OH)D and <strong>24-hour urine calcium or calcium/creatinine clearance ratio</strong>. Low urine calcium suggests FHH, while primary disease commonly has normal/high urinary calcium. Localization imaging comes after biochemical diagnosis when surgery is planned.</p>',['pth-dependent-causes','pthdep-creatinine-phos-vitd','urine-calcium-fhh','localize-after-diagnosis'],[
        q('What does high calcium with nonsuppressed PTH indicate?','A PTH-dependent hypercalcemia pathway',['PTHrP-mediated malignancy is proven','Vitamin D intoxication is proven','Granulomatous calcitriol excess is proven'],'PTH should normally be low during hypercalcemia.'),
        q('Which test helps distinguish FHH from primary hyperparathyroidism?','24-hour urine calcium or calcium/creatinine clearance ratio',['Chest CT before biochemical assessment','Random ACTH','Serum metanephrines'],'FHH typically has low urinary calcium.')
      ],[q('A young patient has lifelong mild hypercalcemia, nonsuppressed PTH, family history and very low urine calcium. Which diagnosis needs consideration before surgery?','Familial hypocalciuric hypercalcemia',['Hypercalcemia of malignancy','Vitamin D intoxication','Hungry bone syndrome'],'FHH usually does not benefit from parathyroid surgery.')]),
      u('PTH suppressed: investigate non-parathyroid causes','<p>With appropriately low PTH, measure based on context: <strong>PTHrP</strong> for humoral malignancy, <strong>25(OH)D</strong> for supplement toxicity, and <strong>1,25(OH)2D</strong> for granulomatous disease/lymphoma.</p><p>Also consider osteolytic cancer, medications, thyrotoxicosis, immobilization and other causes; use CBC, renal tests, protein studies or imaging as clinically indicated.</p>',['pth-independent-low','pthrp-malignancy','25ohd-toxicity','125-granuloma-lymphoma','other-causes-targeted'],[
        q('What does elevated PTHrP with suppressed intact PTH suggest?','Humoral hypercalcemia of malignancy',['Primary hyperparathyroidism','Hypoparathyroidism','FHH'],'Tumor-produced PTHrP mimics PTH effects while suppressing native PTH.'),
        q('Which vitamin D metabolite is often high in granulomatous hypercalcemia?','1,25-dihydroxyvitamin D',['Only 25-hydroxyvitamin D from supplement overdose','PTHrP','Calcitonin'],'Extra-renal macrophage activation raises calcitriol.')
      ],[q('Hypercalcemia is confirmed, PTH is suppressed, PTHrP is normal, and calcitriol is elevated. Which cause should be investigated?','Granulomatous disease or lymphoma',['Primary parathyroid adenoma','FHH','Postsurgical hypoparathyroidism'],'The pattern is PTH-independent and calcitriol-mediated.')])
    ]),
    s('07-laboratory-patterns','7. Characteristic laboratory patterns','Objective 7. Slides 35–38, 55, 67–72, 90–99.',[
      u('Compare calcium, PTH, phosphate, and vitamin D signals','<table><thead><tr><th>Disorder</th><th>Ca</th><th>PTH</th><th>Phosphate</th><th>Key marker</th></tr></thead><tbody><tr><td>Primary HPT</td><td>High</td><td>High/inappropriate</td><td>Low</td><td>Urine Ca often normal/high</td></tr><tr><td>Secondary HPT, CKD</td><td>Low/normal</td><td>High</td><td>High</td><td>Low calcitriol</td></tr><tr><td>Secondary HPT, vitamin D loss</td><td>Low/normal</td><td>High</td><td>Low/normal</td><td>Low 25(OH)D</td></tr><tr><td>PTHrP malignancy</td><td>High</td><td>Low</td><td>Low</td><td>High PTHrP</td></tr><tr><td>Vitamin D intoxication</td><td>High</td><td>Low</td><td>High/normal</td><td>High 25(OH)D</td></tr><tr><td>Granulomatous/lymphoma</td><td>High</td><td>Low</td><td>High/normal</td><td>High 1,25(OH)2D</td></tr></tbody></table>',['pattern-primary','pattern-secondary-ckd','pattern-secondary-vitd','pattern-pthrp','pattern-vitd-tox','pattern-granuloma'],[
        q('Which pattern fits primary hyperparathyroidism?','High calcium, nonsuppressed PTH, and often low phosphate',['Low calcium, low PTH, high phosphate','High calcium, low PTH, high PTHrP','High calcium, low PTH, high calcitriol'],'PTH is inappropriate for the high calcium and wastes phosphate.'),
        q('Which pattern fits CKD-related secondary hyperparathyroidism?','High PTH, high phosphate, low calcitriol, and low/normal calcium',['High calcium, low PTH, low phosphate','High calcium, high PTH with low urine calcium as FHH','Low PTH with high calcium'],'Kidney failure causes phosphate retention and impaired vitamin D activation.'),
        q('Which marker distinguishes vitamin D intoxication from granulomatous disease?','25(OH)D is high in intoxication; 1,25(OH)2D is high in granulomatous disease',['PTHrP is high in both','PTH must be high in both','Phosphate must be low in both'],'Measure the metabolite that matches the mechanism.')
      ],[q('Labs show Ca high, PTH low, phosphate high-normal, 25(OH)D normal and 1,25(OH)2D high. Which row fits?','Granulomatous disease or lymphoma',['Primary hyperparathyroidism','CKD secondary hyperparathyroidism','FHH'],'Suppressed PTH plus high calcitriol localizes the mechanism.')]),
      u('Use the physiologic response, not a memorized label','<p>Ask whether PTH is appropriate for the calcium. High calcium should suppress PTH; low calcium should raise it.</p><p>Then use phosphate, kidney function, vitamin D metabolites, PTHrP and urine calcium to narrow the cause. No single pattern replaces clinical context, and mixed disease can blur textbook values.</p>',['pattern-pth-appropriate','pattern-second-line-markers','pattern-context-mixed'],[
        q('What is the fastest way to organize calcium-disorder labs?','Start with calcium and whether PTH is appropriately suppressed or elevated',['Start with a neck image before confirming labs','Use phosphate alone','Assume all high calcium is primary HPT'],'The feedback relationship creates the main diagnostic branch.')
      ],[q('A patient with low calcium has a low PTH. Is that an appropriate response?','No; it suggests hypoparathyroidism or impaired PTH secretion',['Yes; low calcium should suppress PTH','Yes; it proves secondary hyperparathyroidism','No; it proves malignancy'],'Low calcium should normally stimulate PTH.')])
    ]),
    s('08-primary-hyperparathyroidism','8. Primary hyperparathyroidism','Objective 8. Slides 49–58, with current workup and surgical criteria.',[
      u('Causes and usual presentation','<p>A single autonomous <strong>adenoma</strong> causes about 80–85% of cases; multigland hyperplasia causes most of the remainder. Parathyroid carcinoma is rare. Consider hereditary syndromes/multigland disease in young patients or strong family histories.</p><p>Primary HPT is common after age 50 and more common in women. Many outpatients have mild, incidentally discovered hypercalcemia.</p>',['phpt-adenoma','phpt-hyperplasia','phpt-carcinoma-rare','phpt-hereditary-young','phpt-older-women','phpt-incidental-mild'],[
        q('What is the most common cause of primary hyperparathyroidism?','A single parathyroid adenoma',['Parathyroid carcinoma','Chronic kidney disease','Vitamin D intoxication'],'Most cases arise from one autonomous gland.'),
        q('What is the usual modern presentation?','Mild hypercalcemia found incidentally in an outpatient',['Adrenal crisis','Severe tetany in every patient','Calciphylaxis in every patient'],'Classic symptoms remain important but many cases are detected on labs.')
      ],[q('A 62-year-old woman has repeated mild hypercalcemia and nonsuppressed PTH without symptoms. Which diagnosis fits?','Primary hyperparathyroidism',['Secondary HPT from CKD','Hypoparathyroidism','Hungry bone syndrome'],'The outpatient pattern is typical of primary disease.')]),
      u('Stones, bones, groans, and psychiatric changes','<p><strong>Stones:</strong> hypercalciuria, nephrolithiasis, polyuria/polydipsia and impaired kidney function. <strong>Bones:</strong> bone pain, low density/osteoporosis, cystic change and fractures from chronic PTH excess.</p><p><strong>Groans:</strong> constipation, dyspepsia, nausea/vomiting, occasionally pancreatitis. Neuropsychiatric findings include fatigue, poor memory/concentration, depression, confusion or worse with severe calcium elevation.</p>',['phpt-stones-renal','phpt-polyuria-kidney','phpt-bone-pain-density-fracture','phpt-gi','phpt-neuropsychiatric'],[
        q('What does “stones” refer to in primary HPT?','Hypercalciuria and renal calculi',['Gallstones only','Pituitary masses','Skin calcium deposition only'],'PTH-driven hypercalcemia can increase filtered urinary calcium.'),
        q('Which skeletal effects can chronic PTH excess cause?','Bone loss, pain, osteoporosis and fracture',['Uniformly stronger bone','Only muscle hypertrophy','No skeletal effect'],'Persistent resorption weakens bone.')
      ],[q('A patient with high calcium and nonsuppressed PTH has kidney stones and osteoporosis. How are these linked?','Primary HPT can increase urinary calcium and reduce skeletal strength',['The two findings rule out parathyroid disease','Only low calcium causes both','PTH protects bone while causing stones independently'],'They represent renal and skeletal target-organ involvement.')]),
      u('Diagnosis and complication assessment','<p>Diagnosis: repeated corrected/ionized hypercalcemia with <strong>elevated or inappropriately normal PTH</strong>; phosphate often low.</p><p>Assess creatinine clearance/eGFR, 25(OH)D, <strong>24-hour urine calcium</strong>, renal imaging for stones, and DXA at lumbar spine, hip and distal one-third radius; evaluate vertebral fracture when indicated. Exclude FHH before surgery. Imaging localizes glands only after deciding on surgery.</p>',['phpt-labs-ca-pth-phos','phpt-kidney-vitd-urine','phpt-renal-imaging','phpt-dxa-three-sites','phpt-vertebral','phpt-exclude-fhh','phpt-localization-after'],[
        q('Which biochemical combination diagnoses primary HPT?','Repeated high calcium with elevated or inappropriately normal PTH',['Low calcium with low PTH','High calcium with fully suppressed PTH','Low calcium with high phosphate only'],'PTH is not appropriately suppressed.'),
        q('Why obtain urine calcium before parathyroid surgery?','Assess renal risk and help distinguish FHH',['Locate the exact gland','Measure calcitriol production','Diagnose PTHrP malignancy'],'Very low urine calcium can signal FHH.')
      ],[q('A patient with mild lifelong hypercalcemia and nonsuppressed PTH is sent for surgery without urine calcium assessment. What important alternative could be missed?','Familial hypocalciuric hypercalcemia',['Hypercalcemia of malignancy with suppressed PTH','Postsurgical hypoparathyroidism','Hungry bone syndrome'],'FHH commonly does not benefit from parathyroidectomy.')]),
      u('Parathyroidectomy and monitoring','<p><strong>Parathyroidectomy</strong> is definitive and recommended for symptomatic disease. Current asymptomatic criteria include any of: calcium &gt;1 mg/dL above the upper limit; age &lt;50; osteoporosis/vertebral fracture; kidney stone/nephrocalcinosis; creatinine clearance/eGFR &lt;60; or hypercalciuria (&gt;250 mg/day women, &gt;300 mg/day men).</p><p>Patients without criteria may undergo surgery by informed choice or be monitored with calcium, kidney and skeletal follow-up. Hydration and avoidance of aggravating factors support conservative care. '+phpt+'</p>',['phpt-surgery-symptomatic','phpt-surgery-calcium-age','phpt-surgery-skeletal','phpt-surgery-renal','phpt-surgery-hypercalciuria','phpt-monitor-conservative'],[
        q('Which asymptomatic patient meets a surgical criterion?','A 44-year-old with confirmed primary HPT',['A 70-year-old with no criteria automatically requires no discussion','A patient with normal calcium and suppressed PTH','A patient with FHH as the default surgical indication'],'Age under 50 is a current criterion.'),
        q('Which renal finding supports parathyroidectomy?','Kidney stone, CrCl/eGFR below 60, or significant hypercalciuria',['Normal renal imaging and function only','Low PTHrP alone','Normal urine calcium alone'],'Renal target-organ involvement changes management.')
      ],[q('An asymptomatic patient has confirmed primary HPT, T-score −2.7 and a prior vertebral fracture. Which treatment direction fits?','Refer for experienced parathyroid surgery',['Observe solely because there is no pain','Treat only with calcium supplements','Diagnose secondary HPT'],'Skeletal involvement meets a surgical criterion.')]),
      u('Postoperative complications','<p>Monitor ionized/serum calcium after surgery. Transient hypocalcemia can occur; prolonged profound hypocalcemia suggests hungry bone syndrome.</p><p>Other surgical risks include recurrent laryngeal nerve injury, bleeding and permanent hypoparathyroidism. Thyroid manipulation can rarely produce transient thyrotoxic symptoms; this is not an expected defining complication in every patient.</p>',['phpt-postop-calcium','phpt-hungrybone-preview','phpt-rlN-bleed-hypopara','phpt-thyroid-manipulation'],[
        q('Which postoperative laboratory problem requires close monitoring?','Hypocalcemia',['Mandatory hypernatremia','PTHrP excess','Vitamin D intoxication'],'PTH can fall rapidly after removal of overactive tissue.'),
        q('Which anatomic complication can cause postoperative hoarseness?','Recurrent laryngeal nerve injury',['Osteoclast inhibition','PTHrP secretion','Renal phosphate retention'],'The nerve runs near the operative field.')
      ],[q('After parathyroidectomy, a patient develops hoarseness and falling calcium. Which concerns fit?','Recurrent laryngeal nerve injury and postoperative hypocalcemia',['Hypercalcemia of malignancy and pheochromocytoma','Only expected findings needing no assessment','Primary aldosteronism'],'Both are recognized postoperative issues.')])
    ]),
    s('09-hungry-bone','9. Hungry bone syndrome','Objective 9. Slides 59–64.',[
      u('Why calcium moves rapidly into bone','<p>Before surgery, severe prolonged PTH excess drives high bone turnover. After successful parathyroidectomy, resorption falls rapidly while osteoblast-driven formation/mineralization continues.</p><p>Calcium, phosphate and magnesium move from blood into demineralized bone, producing <strong>prolonged hypocalcemia</strong> despite low/normal postoperative PTH.</p>',['hbs-high-turnover-before','hbs-resorption-stops','hbs-formation-continues','hbs-ca-phos-mg-uptake','hbs-prolonged-lowca'],[
        q('What causes hungry bone syndrome?','Rapid skeletal mineral uptake after abrupt removal of chronic PTH excess',['Continued autonomous PTH driving hypercalcemia','PTHrP secretion after surgery','Excess oral calcium absorption'],'Bone formation continues after resorption abruptly decreases.'),
        q('Which minerals can fall?','Calcium, phosphate, and magnesium',['Only sodium','Only potassium','Only chloride'],'Mineralization consumes more than calcium alone.')
      ],[q('After parathyroidectomy, calcium remains low despite repeated replacement, with low phosphate and magnesium. Which syndrome fits?','Hungry bone syndrome',['Tertiary hyperparathyroidism','Vitamin D intoxication','FHH'],'The prolonged postoperative mineral uptake pattern is characteristic.')]),
      u('Risk, presentation, and treatment','<p>Risk is highest with severe bone disease/high turnover, very high PTH/ALP, large gland burden, and renal secondary/tertiary HPT. Symptoms are those of hypocalcemia: paresthesias, cramps, tetany, seizures or QT prolongation.</p><p>The lecture uses failure to normalize by about <strong>4 days</strong> as a clue. Treat with frequent monitoring and substantial calcium, active vitamin D, and magnesium replacement as needed.</p>',['hbs-risk-bone-pth-alp','hbs-risk-renal','hbs-hypoca-symptoms','hbs-fourday-clue','hbs-calcium-calcitriol-mag'],[
        q('Who is at increased hungry-bone risk?','A patient with severe high-turnover bone disease from marked HPT',['A patient with normal PTH and normal bone turnover','A patient with isolated PTHrP excess only','Every patient taking one calcium tablet'],'The larger the remodeling imbalance, the greater the uptake after surgery.'),
        q('How is hungry bone syndrome treated?','Sustained calcium plus active vitamin D, with magnesium correction and monitoring',['IV bisphosphonate to lower calcium further','Fluid restriction only','Thiazide alone without calcium'],'Replacement continues until skeletal uptake slows.')
      ],[q('An ESRD patient undergoes parathyroidectomy and develops persistent tetany with low calcium four days later. What management fits?','Frequent labs and aggressive calcium/calcitriol replacement, correcting magnesium',['Assume a normal transient dip and discharge untreated','Give denosumab','Give PTHrP'],'Renal secondary HPT creates high hungry-bone risk.')])
    ]),
    s('10-secondary-hyperparathyroidism','10. Secondary hyperparathyroidism','Objective 10. Slides 66–85.',[
      u('Affected populations and causes','<p>Secondary HPT is an appropriate compensatory PTH rise from chronic calcium/vitamin D/phosphate disturbance. Major groups: <strong>CKD</strong>, severe vitamin D deficiency and malabsorption such as celiac disease, chronic pancreatitis or gastric bypass.</p><p>The glands are responding to an external stimulus rather than initially secreting autonomously.</p>',['shpt-compensatory','shpt-ckd','shpt-vitd-def','shpt-malabsorption','shpt-not-autonomous'],[
        q('What is the most important population for severe secondary HPT?','Patients with advanced chronic kidney disease',['Healthy patients with a single adenoma','Patients with FHH only','Patients after curative parathyroid surgery only'],'CKD disrupts phosphate and vitamin D/calcium handling.'),
        q('Which nonrenal problems can cause secondary HPT?','Severe vitamin D deficiency or malabsorption',['PTHrP-producing cancer','Vitamin D intoxication','Autonomous parathyroid carcinoma only'],'Poor calcium/vitamin D availability chronically stimulates PTH.')
      ],[q('A gastric-bypass patient has low vitamin D, low-normal calcium and high PTH. Which process fits?','Secondary hyperparathyroidism from malabsorption',['Primary HPT','Tertiary HPT','Hypercalcemia of malignancy'],'The PTH rise compensates for reduced calcium/vitamin D absorption.')]),
      u('CKD mechanism and laboratory pattern','<p>Kidneys retain <strong>phosphate</strong> and make less <strong>calcitriol</strong>. Less intestinal calcium absorption plus phosphate binding lowers ionized calcium. High phosphate, low calcium and low calcitriol each promote PTH secretion and gland hyperplasia.</p><p>Typical advanced CKD pattern: <strong>PTH high, phosphate high, calcitriol low, calcium low or low-normal</strong>. Interpret serial values together. '+ckd+'</p>',['shpt-ckd-phos-retain','shpt-ckd-low-calcitriol','shpt-lowca-stimuli','shpt-gland-hyperplasia','shpt-ckd-lab-pattern','shpt-serial-together'],[
        q('Why does CKD raise PTH?','Phosphate retention and low calcitriol reduce calcium signaling and chronically stimulate the glands',['Kidneys produce too much calcitriol','CKD always causes an autonomous adenoma first','PTHrP replaces PTH'],'Several CKD abnormalities reinforce secondary HPT.'),
        q('Which pattern fits CKD secondary HPT?','High PTH/high phosphate/low calcitriol with low-normal calcium',['High calcium/low PTH/high PTHrP','High calcium/high PTH/low phosphate after transplant','Low calcium/low PTH/high phosphate'],'The PTH response remains driven by CKD mineral imbalance.')
      ],[q('An ESRD patient has phosphate 6.8, low calcitriol, low-normal calcium and high PTH. What is the mechanism?','CKD-related secondary hyperparathyroidism',['Primary adenoma','Vitamin D intoxication','PTHrP malignancy'],'The failing kidney creates all major stimuli for PTH.')]),
      u('Complications: renal osteodystrophy and calcification','<p>Chronic PTH excess causes high-turnover bone loss, pain, weakness and fractures within <strong>renal osteodystrophy/CKD-MBD</strong>.</p><p>High calcium-phosphate burden promotes vascular/valvular and soft-tissue calcification. <strong>Calciphylaxis</strong> is painful ischemic skin necrosis from small/medium-vessel calcification, seen mainly in advanced CKD.</p>',['shpt-renal-osteodystrophy','shpt-bone-pain-fracture','shpt-vascular-valve-calc','shpt-calciphylaxis'],[
        q('What is renal osteodystrophy?','Bone disease caused by CKD mineral/hormone abnormalities',['A single parathyroid adenoma','Vitamin D intoxication only','PTH resistance with normal kidneys only'],'Secondary HPT is one important contributor to CKD-MBD bone disease.'),
        q('What is calciphylaxis?','Painful ischemic skin necrosis from vascular calcification in advanced CKD',['A benign calcium rash','A normal response to dialysis','An isolated thyroid nodule'],'It is a severe, high-mortality complication requiring urgent care.')
      ],[q('A dialysis patient develops exquisitely painful retiform skin lesions with necrosis. Which complication should be considered?','Calciphylaxis',['Chvostek sign','Paget disease','Simple calcium supplement intolerance'],'The skin pattern in advanced CKD is an emergency.')]),
      u('Treatment follows phosphate, vitamin D, calcium, and PTH trends','<p>Limit excess dietary phosphate and use binders <strong>with meals</strong> for persistent hyperphosphatemia. Choose calcium-based versus noncalcium binders based on calcium/calcification risk.</p><p>Correct vitamin D deficiency; selected advanced CKD/dialysis patients may receive calcitriol or analogs. Dialysis patients with persistent high PTH may receive <strong>cinacalcet</strong> or IV <strong>etelcalcetide</strong>, which sensitize the calcium-sensing receptor.</p><p>Severe refractory disease can require subtotal or total parathyroidectomy. Therapy uses serial Ca/phosphate/PTH rather than one value. '+ckd+'</p>',['shpt-diet-phosphate','shpt-binders-meals','shpt-binder-calcium-choice','shpt-vitd-calcitriol-analogs','shpt-cinacalcet-etelcalcetide','shpt-casr-mechanism','shpt-surgery-refractory'],[
        q('How should phosphate binders be taken?','With meals to bind ingested phosphate',['On an empty stomach once monthly','Only during sleep','With no relationship to food'],'They must be present when dietary phosphate enters the gut.'),
        q('How do calcimimetics lower PTH?','Increase calcium-sensing receptor sensitivity',['Replace calcitriol directly','Remove phosphate through the lungs','Stimulate autonomous gland growth'],'The gland perceives more calcium signal and reduces secretion.'),
        q('When is parathyroidectomy considered in secondary HPT?','Severe disease that fails aggressive medical therapy',['Every early CKD PTH rise','Before correcting vitamin D or phosphate','Only after PTH becomes low'],'Surgery is reserved for refractory severe disease.')
      ],[q('A dialysis patient has persistently high phosphate and PTH despite diet. Which sequence fits?','Use meal-time phosphate binders, optimize vitamin D/mineral management, and consider a calcimimetic based on serial labs',['Give calcium blindly without checking phosphate','Stop all dialysis-related care','Diagnose primary HPT solely from high PTH'],'CKD treatment targets the multiple drivers together.')])
    ]),
    s('11-tertiary-hyperparathyroidism','11. Progression to tertiary hyperparathyroidism','Objective 11. Slides 87–89.',[
      u('Long stimulation becomes autonomous secretion','<p>Years of CKD-related secondary stimulation cause gland hyperplasia. Some glands become autonomous and continue secreting PTH even when the original stimulus improves, often recognized after kidney transplant.</p><p>Result: <strong>very high/nonsuppressed PTH with hypercalcemia</strong>. Phosphate may fall after restored kidney function because PTH drives phosphaturia; in persistent kidney failure it may remain high.</p>',['thpt-secondary-to-autonomous','thpt-post-transplant','thpt-high-pth-high-ca','thpt-phos-kidney-dependent'],[
        q('What converts secondary into tertiary hyperparathyroidism?','Long-standing gland hyperplasia becomes autonomous',['PTH abruptly disappears','A tumor begins making PTHrP only','Vitamin D intoxication suppresses all glands'],'The gland no longer responds normally to corrected calcium signals.'),
        q('Which pattern after kidney transplant suggests tertiary HPT?','Persistent high PTH with hypercalcemia',['Low PTH with hypocalcemia','Suppressed PTH with high PTHrP','Normal calcium with corrected PTH'],'The recovered kidney removes the original stimulus, but secretion persists.')
      ],[q('A transplant recipient has restored kidney function but persistent PTH 900 and calcium 11.8. Which diagnosis fits?','Tertiary hyperparathyroidism',['Resolved secondary HPT','Hypoparathyroidism','Vitamin D deficiency alone'],'Autonomous secretion persists after correction of the original renal trigger.')]),
      u('Complications and treatment','<p>Persistent hypercalcemia can cause renal, skeletal and soft-tissue calcification complications. Calcimimetic therapy may control some cases.</p><p>Resistant or severe disease is treated with <strong>subtotal parathyroidectomy</strong> or total parathyroidectomy with selected autotransplantation. Hungry bone syndrome is an important postoperative risk.</p>',['thpt-hyperca-complications','thpt-calcimimetic','thpt-surgery','thpt-hungrybone-risk'],[
        q('What is standard treatment for severe resistant tertiary HPT?','Subtotal or total parathyroidectomy with an appropriate surgical plan',['Calcium supplementation as the only therapy','PTH injection','No treatment despite severe hypercalcemia'],'Autonomous glands may require removal.')
      ],[q('A tertiary HPT patient remains severely hypercalcemic despite calcimimetic therapy. What is the next standard direction?','Parathyroid surgery with postoperative calcium planning',['Add high-dose calcium before correcting the hypercalcemia','Treat as hypoparathyroidism','Use PTHrP testing as definitive therapy'],'Refractory autonomous secretion is a surgical disease.')])
    ]),
    s('12-malignancy-hypercalcemia','12. Hypercalcemia of malignancy','Objective 12. Slides 35, 38, 90–91, with current treatment completion.',[
      u('Three major malignant mechanisms','<p><strong>Humoral PTHrP:</strong> common with squamous cancers and some renal, breast, ovarian or other solid tumors. <strong>Osteolytic disease:</strong> myeloma or bone metastases release calcium locally. <strong>Calcitriol-mediated:</strong> lymphoma and some granulomatous tumor settings.</p><p>Parathyroid carcinoma is a rare true-PTH malignancy and follows a different biochemical pathway.</p>',['hcm-pthrp-solid','hcm-squamous','hcm-osteolytic-myeloma-metastasis','hcm-calcitriol-lymphoma','hcm-parathyroid-carcinoma'],[
        q('What is the common humoral mechanism of malignancy hypercalcemia?','Tumor secretion of PTHrP',['Tumor secretion of intact PTH in most cancers','Loss of all osteoclast activity','Calcitonin excess'],'PTHrP mimics key PTH actions.'),
        q('Which cancer pattern causes hypercalcemia through osteolysis?','Multiple myeloma or destructive bone metastases',['A nonfunctioning pituitary microadenoma','A benign thyroid cyst','FHH'],'Bone destruction releases mineral independent of PTHrP in some cases.')
      ],[q('A patient with squamous lung cancer develops rapid severe hypercalcemia, suppressed PTH and high PTHrP. What mechanism fits?','Humoral hypercalcemia of malignancy',['Primary HPT','Tertiary HPT','Vitamin D deficiency'],'The tumor peptide produces a PTH-like biochemical effect.')]),
      u('Presentation and laboratory patterns','<p>Hypercalcemia of malignancy often develops rapidly and causes dehydration, polyuria, weakness, constipation, confusion or coma. It is common among hospitalized severe hypercalcemia cases.</p><p><strong>PTHrP pattern:</strong> Ca high, intact PTH low, PTHrP high, phosphate often low. <strong>Osteolytic pattern:</strong> PTH low, PTHrP may be normal. <strong>Calcitriol pattern:</strong> PTH low and 1,25(OH)2D high.</p>',['hcm-rapid-severe-symptoms','hcm-hospitalized','hcm-pthrp-pattern','hcm-osteolytic-pattern','hcm-calcitriol-pattern'],[
        q('Which lab pattern fits PTHrP-mediated malignancy?','High calcium, low intact PTH, high PTHrP',['High calcium, high intact PTH, low PTHrP','Low calcium, low PTH, high phosphate','High calcium with very low urine calcium and family history'],'Native PTH suppresses because calcium is high.'),
        q('Can malignancy cause hypercalcemia with normal PTHrP?','Yes, through osteolytic or calcitriol-mediated mechanisms',['No, PTHrP must be high in every cancer case','No, only parathyroid adenomas cause high calcium','Yes, but PTH must always be high'],'Mechanism-specific testing matters.')
      ],[q('A myeloma patient has hypercalcemia, suppressed PTH and normal PTHrP with extensive lytic lesions. Which mechanism fits?','Osteolytic calcium release',['Primary HPT','FHH','Hypoparathyroidism'],'PTHrP is not required when bone destruction drives calcium release.')]),
      u('Acute treatment and recurrence prevention','<p>Give isotonic IV fluid for volume depletion, adjusted to comorbidity. All adults with HCM should receive <strong>denosumab or an IV bisphosphonate</strong>; current guidance suggests denosumab over IV bisphosphonate in many cases.</p><p>For severe HCM (&gt;14 mg/dL), add <strong>calcitonin</strong> as a rapid bridge for only 48–72 hours. Treat the cancer. Use glucocorticoids first for calcitriol-mediated HCM, adding antiresorptive treatment if needed. '+hcm+'</p>',['hcm-iv-fluid','hcm-denosumab-bp','hcm-denosumab-preference','hcm-severe14-calcitonin','hcm-calcitonin72','hcm-treat-cancer','hcm-calcitriol-steroid'],[
        q('Which sustained calcium-lowering treatment is recommended for HCM?','Denosumab or an IV bisphosphonate',['Oral calcium supplementation','Thiazide therapy','PTH injection'],'Antiresorptive therapy controls calcium while cancer treatment addresses the source.'),
        q('What is recommended initially for severe HCM above 14 mg/dL?','Calcitonin plus denosumab or an IV bisphosphonate',['Calcitonin alone indefinitely','Oral hydration only','Vitamin D loading'],'Calcitonin bridges the slower antiresorptive onset.')
      ],[q('A patient with cancer has calcium 15.5, confusion and dehydration. Which plan fits?','Urgent IV fluid, short-course calcitonin, antiresorptive therapy, and cancer-directed care',['Outpatient observation only','Calcium and vitamin D supplementation','A thiazide plus bed rest'],'Severe HCM needs immediate and sustained treatment.')]),
      u('Treatment risks and special circumstances','<p>Assess kidney function, dental risk and hypocalcemia/vitamin D status when choosing antiresorptive therapy. Denosumab is useful in renal impairment but can cause profound hypocalcemia.</p><p>Refractory/recurrent HCM after IV bisphosphonate can be treated with denosumab. Dialysis may be necessary in life-threatening refractory disease or when fluid therapy is unsafe.</p>',['hcm-treatment-renal-dental','hcm-denosumab-hypocalcemia','hcm-refractory-denosumab','hcm-dialysis'],[
        q('Which risk requires close attention after denosumab, especially with kidney disease?','Hypocalcemia',['Hyperparathyroidism is impossible','Immediate vitamin D intoxication','PTHrP production by the drug'],'Potent antiresorption can drop calcium substantially.')
      ],[q('HCM persists after IV bisphosphonate. Which guideline-supported next option can be considered?','Denosumab',['Calcium chloride','Lithium','A thiazide'],'Denosumab is recommended for refractory/recurrent disease after bisphosphonate.')])
    ]),
    s('13-hypoparathyroidism','13. Hypoparathyroidism','Objective 13. Slides 93–98, completed with chronic-treatment monitoring.',[
      u('Causes: surgery first, then autoimmune/genetic/infiltrative','<p><strong>Anterior neck surgery</strong> is the most common cause and may cause transient or permanent disease. Other causes include autoimmune destruction/calcium-sensing receptor antibodies, genetic syndromes, radiation and infiltrative/iron or copper disorders.</p><p>Severe persistent <strong>hypomagnesemia</strong> can reversibly suppress PTH and cause resistance, especially with malnutrition or heavy alcohol use.</p>',['hypopara-surgery-common','hypopara-autoimmune-genetic','hypopara-radiation-infiltrative','hypopara-magnesium-reversible'],[
        q('What is the most common cause of hypoparathyroidism?','Thyroid or parathyroid surgery',['Primary parathyroid adenoma','CKD','PTHrP-producing cancer'],'The glands may be removed, injured or devascularized during neck surgery.'),
        q('Which reversible problem can mimic/cause hypoparathyroid physiology?','Severe hypomagnesemia',['Hypermagnesemia in every case','High PTHrP','Vitamin D intoxication'],'Magnesium is required for secretion and response.')
      ],[q('After thyroidectomy, a patient develops perioral tingling, spasm and low calcium. Which cause is most likely?','Postsurgical hypoparathyroidism',['Primary HPT','Tertiary HPT','Hypercalcemia of malignancy'],'Timing and symptoms point to loss of PTH function.')]),
      u('Clinical and laboratory presentation','<p>Symptoms come from hypocalcemia: paresthesias, cramps/tetany, Chvostek/Trousseau signs, laryngospasm/bronchospasm, seizures, prolonged QT and mood/cognitive changes.</p><p>Labs: <strong>low calcium, low or inappropriately normal PTH, high phosphate</strong>; magnesium may be low and calcitriol reduced. Chronic disease can cause kidney stones/nephrocalcinosis from treatment-related hypercalciuria.</p>',['hypopara-hypoca-symptoms','hypopara-lowca-lowpth-highphos','hypopara-lowmg-calcitriol','hypopara-renal-treatment-complications'],[
        q('Which pattern fits hypoparathyroidism?','Low calcium, low PTH, high phosphate',['Low calcium, high PTH, low phosphate','High calcium, high PTH, low phosphate','High calcium, low PTH, high PTHrP'],'Without PTH, kidney phosphate excretion falls and calcium support falls.'),
        q('Why can chronic treatment cause kidney stones?','High oral calcium/active vitamin D can produce hypercalciuria',['Low PTH always prevents urine calcium','PTHrP is produced by calcium tablets','Phosphate cannot affect the kidney'],'Monitoring must include urine as well as serum calcium.')
      ],[q('A patient has low calcium, high phosphate and low PTH after neck surgery. Which diagnosis fits?','Hypoparathyroidism',['Secondary HPT','Primary HPT','Vitamin D intoxication'],'The PTH response is inappropriately low.')]),
      u('Acute and chronic treatment','<p>Acute symptomatic disease uses monitored <strong>IV calcium gluconate</strong>, with magnesium correction. Stabilize on oral therapy before discharge.</p><p>Chronic first-line care uses oral calcium plus <strong>active vitamin D (calcitriol)</strong>, targeting the lower normal calcium range while avoiding hypercalciuria and high phosphate. Calcium with meals can reduce phosphate absorption. '+hypo+'</p>',['hypopara-acute-gluconate-mag','hypopara-chronic-calcium-calcitriol','hypopara-low-normal-target','hypopara-avoid-urine-phos','hypopara-calcium-meals'],[
        q('What is first-line chronic hypoparathyroidism treatment?','Oral calcium plus active vitamin D',['An IV bisphosphonate','Cinacalcet to suppress already-low PTH','A thiazide alone without calcium/vitamin D'],'Calcitriol replaces the PTH-dependent activation step.'),
        q('What calcium target is preferred?','Lower half of normal or just below while symptoms are controlled',['Persistent high-normal hypercalcemia','As low as possible despite tetany','A fixed total calcium regardless of symptoms or urine calcium'],'Avoiding hypercalciuria is part of the target.')
      ],[q('A chronic hypoparathyroid patient has normal-high serum calcium but recurrent stones and high urine calcium. What should management prioritize?','Adjust therapy to reduce hypercalciuria while maintaining symptom control',['Raise serum calcium further','Stop monitoring urine calcium','Add more calcium automatically'],'A serum target alone can hide renal treatment toxicity.')]),
      u('Thiazide and PTH replacement for selected patients','<p>Thiazides with a low-sodium diet can reduce urinary calcium; monitor BP, potassium, magnesium and kidney function.</p><p>PTH replacement can be considered when conventional therapy is unsatisfactory because of symptoms, poor control, hyperphosphatemia, renal issues, malabsorption/intolerance or excessive supplement requirements. Product availability and safety require specialist management; avoid memorizing the slide’s older blanket osteosarcoma warning as applying identically to every current product.</p>',['hypopara-thiazide-low-salt','hypopara-thiazide-monitor','hypopara-pth-selected','hypopara-pth-indications','hypopara-product-specific'],[
        q('What is the role of a thiazide in hypoparathyroidism?','Reduce hypercalciuria in selected patients',['Raise urinary calcium','Replace PTH directly','Treat acute tetany without calcium'],'Pair it with sodium restriction and monitoring.'),
        q('When might PTH replacement be considered?','When calcium/active-vitamin-D therapy is unsatisfactory or causes complications',['As routine first-line therapy for every patient','For acute seizure before IV calcium','To suppress high PTH in secondary HPT'],'It is a specialist option for difficult chronic control.')
      ],[q('A patient needs very high calcium/calcitriol doses yet remains symptomatic with hypercalciuria. Which escalation may be appropriate?','Specialist evaluation for PTH replacement therapy',['More supplements without limit','IV bisphosphonate','Cinacalcet to further reduce PTH action'],'The conventional regimen is unsatisfactory and causing complications.')])
    ]),
    s('14-pseudohypoparathyroidism','14. Pseudohypoparathyroidism','Objective 14. Slides 94, 99–100.',[
      u('End-organ resistance despite high PTH','<p>Pseudohypoparathyroidism is a group of genetic disorders with <strong>target-organ resistance to PTH</strong>, especially in the kidney.</p><p>The gland senses low calcium and releases more PTH, but the kidney fails to retain calcium appropriately, excrete phosphate, or activate vitamin D normally. Result: <strong>low calcium, high phosphate, high PTH</strong>.</p>',['pseudo-genetic-resistance','pseudo-kidney-target','pseudo-highpth-lowca-highphos','pseudo-low-calcitriol'],[
        q('Which feature distinguishes pseudohypoparathyroidism from true hypoparathyroidism?','PTH is elevated because target tissues resist it',['PTH is always undetectable','Calcium is always high','Phosphate is always low'],'The hormone is present, but signaling fails.')
      ],[q('Labs show low calcium, high phosphate and high PTH with normal kidney function. Which disorder fits?','Pseudohypoparathyroidism',['Postsurgical hypoparathyroidism','Primary HPT','PTHrP malignancy'],'High PTH distinguishes resistance from absent hormone production.')]),
      u('Phenotype and treatment targets','<p>Some subtypes show <strong>Albright hereditary osteodystrophy</strong>: short stature, round face, shortened fourth/fifth metacarpals and ectopic ossification; not every subtype has the full phenotype.</p><p>Treat with calcium and active vitamin D to correct symptoms, lower PTH and avoid hyperphosphatemia/hypercalciuria. Monitor serum and urinary calcium, phosphate and renal health.</p>',['pseudo-aho','pseudo-aho-not-all','pseudo-calcium-calcitriol','pseudo-target-pth-phos-urine','pseudo-monitor-renal'],[
        q('Which physical pattern can occur in some pseudohypoparathyroidism subtypes?','Albright hereditary osteodystrophy',['Marfanoid habitus in every patient','Cushingoid striae from cortisol excess','Frontal bossing from Paget disease only'],'Phenotype varies by genetic subtype.'),
        q('What is the treatment principle?','Calcium plus active vitamin D with biochemical and urinary monitoring',['Parathyroidectomy for hormone resistance','PTH suppression with no calcium support','IV bisphosphonate to lower calcium'],'Treatment bypasses impaired PTH signaling while avoiding renal toxicity.')
      ],[q('A patient with PTH resistance has low calcium symptoms and high phosphate. Which plan fits?','Calcium/calcitriol therapy with monitoring of PTH, phosphate and urine calcium',['Remove the parathyroid glands','Give denosumab','Treat as autonomous PTH excess'],'The hormone is already elevated; the problem is target response.')])
    ])
  ];
})();
